package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMsDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus (Ruku & Sujud)", "(Allah adalah) Maha Suci, Maha Suci, Tuhan para malaikat dan Ruh (Jibril).", "Dalam ruku dan sujud.", "Nabi ﷺ membaca ini dalam ruku dan sujud."),
        "dua_sujood_dhanbi_kullah" to DuaText("Dalam Sujud: Ampunilah Segala Dosaku", "Ya Allah, ampunilah segala dosaku - yang kecil dan yang besar, yang pertama dan yang terakhir, yang nyata dan yang tersembunyi.", "Dalam sujud.", "Sujud adalah tempat dimakbulkan doa."),
        "dua_sujood_ridaka" to DuaText("Berlindung dalam Keredhaan-Mu", "Ya Allah, aku berlindung dengan keridhaan-Mu dari kemurkaan-Mu, dengan ampunan-Mu dari siksa-Mu, dan aku berlindung kepada-Mu dari-Mu. Aku tidak dapat memuji-Mu sepenuhnya; Engkau adalah sebagaimana Engkau telah memuji diri-Mu sendiri.", "Dalam sujud — Aisha (RA) mendengar Nabi ﷺ berkata ini.", "Doa sujud Nabi ﷺ."),
        "dua_tashahhud" to DuaText("Tashahhud (At-Tahiyyat)", "Segala ibadah lisan, fizikal dan kewangan adalah untuk Allah. Salam sejahtera ke atasmu wahai Nabi, dan rahmat Allah serta keberkatan-Nya. Salam sejahtera ke atas kami dan ke atas hamba-hamba Allah yang soleh. Aku bersaksi bahawa tiada yang berhak disembah melainkan Allah, dan aku bersaksi bahawa Muhammad ﷺ adalah hamba dan RasulNya.", "Dalam setiap duduk — diriwayatkan oleh Abdullah ibn Mas'ud (RA) (amalan Hanafi).", "Nabi ﷺ mengajarnya seperti surah al-Quran."),
        "dua_sajdah_tilawah" to DuaText("Sajdah Tilawah", "Wajahku telah sujud kepada yang menciptakannya dan mengeluarkan pendengaran dan penglihatannya dengan kekuatan dan kekuasaan-Nya.", "Dalam sujud tilawah.", "Nabi ﷺ berkata demikian dalam sujud tilawah di malam hari."),
        "dua_after_witr" to DuaText("Selepas Witir", "Maha Suci Raja, Yang Maha Suci.", "Tiga kali selepas salam witir, meninggikan suara kali ketiga.", "Nabi ﷺ berkata demikian selepas witir."),
        "dua_tahajjud_nur" to DuaText("Doa Pembuka Tahajjud", "Ya Allah, bagi-Mu segala puji; Engkaulah yang memelihara langit, bumi dan segala isinya. Kepunyaan-Mu pujian; Engkaulah Cahaya langit, bumi dan segala isinya. Kepunyaan-Mu pujian; Engkaulah yang benar, janji-Mu adalah benar, pertemuan dengan-Mu adalah benar, firman-Mu benar, syurga itu benar, neraka itu benar, para Nabi itu benar, Muhammad ﷺ benar dan hari kiamat itu benar.", "Apabila memulakan solat malam (tahajjud) (bahagian pembuka doa).", "Nabi ﷺ membaca ini semasa bangun tahajjud (doa penuh ada dalam al-Bukhari)."),
        "dua_rabba_jibrail" to DuaText("Bimbing Saya dalam Perkara yang Dipertikaikan", "Ya Allah, Tuhan Jibril, Mikail dan Israfil, Pencipta langit dan bumi, Yang Mengetahui yang ghaib dan yang nyata! Engkau akan memutuskan antara hamba-hamba-Mu tentang apa yang mereka perselisihkan dahulu. Bimbinglah aku dengan izin-Mu kepada kebenaran dalam perkara yang telah diperselisihkan. Sesungguhnya Engkau memberi petunjuk kepada sesiapa yang Engkau kehendaki ke jalan yang lurus.", "Pada permulaan tahajjud - untuk petunjuk kepada kebenaran di tengah-tengah perselisihan.", "Nabi ﷺ memulakan solat malamnya dengan doa ini."),
        "dua_going_to_mosque_nur" to DuaText("Pergi ke Masjid (Dua Cahaya)", "Ya Allah, jadikanlah cahaya di hatiku, cahaya di mataku, cahaya di telingaku, cahaya di kananku, cahaya di kiriku, cahaya di atasku, cahaya di bawahku, cahaya di hadapanku, cahaya di belakangku, dan jadikanlah cahaya untukku.", "Semasa ke masjid untuk Subuh.", "Nabi ﷺ membaca ini ketika keluar untuk solat."),
        "dua_waswasa_salah" to DuaText("Waswasa Semasa Solat (Khinzab)", "Aku berlindung kepada Allah dari syaitan yang terkutuk.", "Apabila bisikan syaitan datang semasa solat, mintalah perlindungan dan ludah kering ke kiri tiga kali.", "Uthman ibn Abil-'As (RA) melakukan ini dan bisikan itu hilang."),
        "dua_alimal_ghayb" to DuaText("Maha Mengetahui perkara yang ghaib", "Ya Allah, Yang Maha Mengetahui yang ghaib dan yang nyata, Pencipta langit dan bumi, Tuhan dan Penguasa segala sesuatu! Aku bersaksi bahawa tiada Tuhan selain Engkau. Aku berlindung kepada-Mu dari kejahatan diriku sendiri, dan dari kejahatan syaitan dan syiriknya.", "Pagi, petang dan sebelum tidur - Nabi ﷺ mengajarkannya kepada Abu Bakar (RA).", "Perlindungan daripada kejahatan diri dan syaitan."),
        "dua_fitratil_islam" to DuaText("Atas Fitrah Islam", "Kami telah memasuki pagi hari atas fitrah Islam, atas kalimah ikhlas, atas agama Nabi kami Muhammad ﷺ dan atas jalan bapa kami Ibrahim (AS), yang lurus lagi Islam, dan bukanlah dari orang-orang musyrik.", "Pada waktu pagi.", "Memperbaharui iman setiap pagi."),
        "dua_amsayna_fitrah" to DuaText("Petang di atas Fitrah Islam", "Kami telah memasuki waktu petang atas fitrah Islam, atas kalimah ikhlas, atas agama Nabi kami Muhammad ﷺ dan atas jalan bapa kami Ibrahim (AS), yang lurus lagi Islam, dan bukanlah dari orang-orang musyrik.", "Pada waktu petang.", "Memperbaharui iman setiap petang."),
        "dua_tahleel_10_fajr" to DuaText("Sepuluh Tahlil Selepas Subuh dan Maghrib", "Tiada yang berhak disembah melainkan Allah semata-mata tiada sekutu. Kepunyaan-Nya kerajaan dan kepunyaan-Nya pujian; Dia menghidupkan dan mematikan, dan Dia Maha Kuasa atas segala sesuatu.", "Sepuluh kali selepas Subuh (dan Maghrib), sebelum bergerak dari duduk atau bercakap.", "Sepuluh kebaikan, sepuluh dosa dihapuskan, sepuluh derajat diangkat dan perlindungan dari syaitan sepanjang hari."),
        "dua_la_hawla_kanz" to DuaText("Harta Jannah", "Tiada daya dan kekuatan melainkan dengan pertolongan Allah.", "Selalunya, pada setiap masa.", "Ia adalah salah satu khazanah Syurga."),
        "dua_four_beloved_words" to DuaText("Empat Kata Yang Paling Disayangi", "Maha Suci Allah, segala puji bagi Allah, tiada yang berhak disembah melainkan Allah, dan Allah Maha Besar.", "Perkataan yang paling dicintai Allah.", "Mereka lebih dicintai oleh Nabi ﷺ daripada segala sesuatu yang matahari terbit."),
        "dua_two_light_words" to DuaText("Dua Perkataan Cahaya di Lidah", "Maha Suci Allah dan bagi-Nya segala pujian; Maha Suci Allah Yang Maha Agung.", "Ringan di lidah, berat di Skala.", "Kekasih Yang Maha Pemurah, ringan di lidah dan berat di timbangan. (Hadis terakhir al-Bukhari)"),
        "dua_ya_dhal_jalal" to DuaText("Ya Dhal-Jalali wal-Ikram", "Wahai Pemilik Keagungan dan Kehormatan!", "Berpeganglah padanya dalam do'a — arahan Nabi ﷺ.", "Nabi ﷺ bersabda: Berpeganglah pada 'Ya Dhal-Jalali wal-Ikram'."),
        "dua_sleep_wadatu_janbi" to DuaText("Atas NamaMu Aku Berbaring", "Dalam nama-Mu, Tuhanku, aku berbaring di sisiku dan dalam nama-Mu aku bangkit. Jika Engkau mencabut nyawaku, kasihanilah dia, dan jika Engkau lepaskan, peliharalah ia sebagaimana Engkau melindungi hamba-hambaMu yang soleh.", "Selepas mengelap katil dan baring.", "Menyerahkan jiwa kepada Allah sebelum tidur."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Anda Mencipta Jiwa Saya", "Ya Allah, Engkau telah menciptakan jiwaku dan Engkau akan mengambilnya. Kematian dan kehidupannya adalah milik-Mu. Jika Engkau menghidupkannya, lindungilah, dan jika Engkau mematikannya, ampunilah. Ya Allah, aku memohon kesejahteraan kepada-Mu.", "Sebelum tidur — diriwayatkan oleh Ibn Umar (RA).", "Nabi ﷺ berpesan mengatakan ini pada waktu tidur."),
        "dua_sleep_atamana" to DuaText("Bersyukur Sebelum Tidur", "Segala puji bagi Allah yang memberi kami makan, memberi kami minum, mencukupkan kami dan memberi kami tempat tinggal. Berapa ramai yang tidak mempunyai sesiapa untuk mencukupkan atau memberi mereka perlindungan.", "Apabila hendak tidur.", "Nabi ﷺ berkata demikian ketika hendak tidur."),
        "dua_sleep_rabbas_samawat" to DuaText("Tuhan Syurga — Bayar Hutang Kami", "Ya Allah, Tuhan langit, bumi dan Arasy yang agung, Tuhan kami dan Tuhan segala sesuatu, Pemecah benih dan kurma, Pewahyu Taurat, Injil dan Furqan! Aku berlindung kepada-Mu dari kejahatan segala sesuatu yang Engkau pegang ubun-ubunnya. Ya Allah, Engkaulah Yang Pertama, tiada sesuatu pun di hadapanMu; Engkaulah Yang Akhir, tidak ada sesuatu pun setelah Engkau; Engkaulah yang nyata, tiada sesuatu pun di atasMu; Engkaulah Yang Tersembunyi, tidak ada yang tersembunyi dariMu. Selesaikan hutang kami dan bebaskanlah kami dari kemiskinan.", "Sebelum tidur, berbaring di sisi kanan — diajarkan kepada Fatimah (RA).", "Doa untuk melepaskan hutang dan kesusahan."),
        "dua_sleep_fear" to DuaText("Ketakutan atau Kegelisahan dalam Tidur", "Aku berlindung dengan kalimat-kalimat Allah yang sempurna dari kemurkaan-Nya dan azab-Nya, dari kejahatan hamba-hamba-Nya, dan dari bisikan syaitan dan dari kedatangan mereka kepadaku.", "Apabila berasa takut atau tidak selesa semasa tidur.", "Melakukannya, perkara itu tidak akan membahayakannya."),
        "dua_waking_afani" to DuaText("Bangun: Dia Memulihkan Jiwaku", "Segala puji bagi Allah yang telah memberikan kesejahteraan kepada tubuhku, mengembalikan rohku kepadaku dan mengizinkan aku mengingatiNya.", "semasa bangun.", "Syukur untuk pagi baru."),
        "dua_allahu_rabbi" to DuaText("Allah, Allah Tuhanku", "Allah, Allah Tuhanku; Aku tidak mempersekutukan-Nya dengan sesuatu pun.", "Dalam kesedihan atau kesusahan - Nabi ﷺ mengajarkannya kepada Asma binti Umays (RA).", "Berpegang teguh pada tauhid di saat kesusahan."),
        "dua_rahmataka_arju" to DuaText("Rahmat-Mu Kuharapkan", "Ya Allah, rahmat-Mulah yang aku harapkan, maka janganlah Engkau serahkan aku kepada diriku sendiri walau sekelip mata, dan perbaikilah segala urusanku. Tiada Tuhan selain Engkau.", "Doa orang yang dalam kesusahan (Da'awat al-makrub).", "Nabi ﷺ menyebutnya doa orang yang dalam kesusahan."),
        "dua_against_enemy_ahzab" to DuaText("Menentang Tentera Musuh", "Ya Allah, Pewahyu Kitab, Cepat hisab! Kalahkan konfederasi. Ya Allah, kalahkan mereka dan goncangkan mereka.", "Menentang musuh - doa Pertempuran Konfederasi.", "Doa Nabi ﷺ terhadap musuh."),
        "dua_anta_adudi" to DuaText("Anda Adalah Sokongan Saya", "Ya Allah, Engkaulah penolong dan penolongku. DenganMu aku merancang, denganMu aku maju dan denganMu aku berperang.", "Sebelum pertandingan atau cabaran besar.", "Nabi ﷺ berkata demikian dalam peperangan."),
        "dua_ikfinihim" to DuaText("Cukuplah Aku Melawan Mereka", "Ya Allah, cukupkanlah aku terhadap mereka sebagaimana yang Engkau kehendaki.", "Menentang kejahatan orang yang zalim — doa budak lelaki dalam kisah Orang Parit.", "Allah menyelamatkan anak itu dari orang-orang yang zalim."),
        "dua_qadarullah" to DuaText("Apabila Sesuatu Yang Buruk Berlaku", "Itu adalah ketetapan Allah, dan Dia melakukan apa yang Dia kehendaki.", "Apabila sesuatu yang tidak menyenangkan berlaku, bukannya berkata 'jika sahaja'.", "'Seandainya' membuka pintu kepada Syaitan."),
        "dua_ala_kulli_hal" to DuaText("Pujian dalam Setiap Situasi", "Segala puji bagi Allah dalam setiap keadaan.", "Apabila sesuatu yang tidak disukai berlaku.", "Nabi ﷺ berkata demikian ketika menghadapi sesuatu yang tidak disukainya."),
        "dua_dogs_barking" to DuaText("Mendengar Anjing menyalak pada waktu malam", "Aku berlindung kepada Allah dari syaitan yang terkutuk.", "Apabila mendengar anjing menyalak atau keldai menjerit pada waktu malam.", "Mereka melihat apa yang anda tidak nampak."),
        "dua_leaving_home_adilla" to DuaText("Perlindungan daripada kesesatan", "Ya Allah, aku berlindung kepada-Mu dari sesat atau disesatkan, dari tergelincir atau tergelincir, dari berbuat zalim atau dizalimi, dari berbuat bodoh atau diperlakukan bodoh.", "Ketika keluar rumah — diriwayatkan oleh Ummu Salamah (RA).", "Nabi ﷺ membaca ini setiap kali baginda meninggalkan rumahnya."),
        "dua_ascending_descending" to DuaText("Naik dan Turun", "Allah Maha Besar (apabila naik). — Maha Suci Allah (ketika turun).", "Dalam perjalanan, sebut 'Allahu Akbar' ketika naik dan 'SubhanAllah' ketika turun.", "Amalan Sahabat (RA) ketika dalam perjalanan."),
        "dua_traveller_sahar" to DuaText("Doa Pengembara Sebelum Subuh", "Seorang pendengar telah mendengar (dan menyampaikan) pujian kita kepada Allah dan nikmat-Nya yang baik kepada kita. Ya Tuhan kami, iringilah kami dan limpahkan karunia-Mu kepada kami - (aku katakan ini) memohon perlindungan kepada Allah dari api neraka.", "Dalam perjalanan, sebelum subuh.", "Nabi ﷺ berkata demikian sebelum subuh ketika bermusafir."),
        "dua_zawwadakallah" to DuaText("Kepada Musafir: Semoga Allah Memberi Taqwa", "Semoga Allah memberikan taqwa untuk perjalananmu, diampuni dosamu dan dipermudahkan segala urusanmu di mana saja kamu berada.", "Apabila mengucapkan selamat tinggal kepada pengembara.", "Nabi ﷺ memberikan doa ini kepada seseorang yang berangkat dalam perjalanan."),
        "dua_traveller_to_resident" to DuaText("Pengembara ke Mereka yang Menginap di Belakang", "Aku serahkan kamu kepada Allah, yang amanah tidak akan hilang.", "Diucapkan oleh musafir ketika mengucapkan selamat tinggal kepada keluarga.", "Menyerahkan keselamatan keluarga kepada Allah."),
        "dua_entering_village" to DuaText("Memasuki Pekan atau Kampung", "Ya Allah, Tuhan tujuh langit dan semua yang dinaungi, Tuhan tujuh bumi dan semua yang dibawanya, Tuhan syaitan dan semua yang mereka sesatkan, Tuhan angin dan semua yang dihamburkan! Kami memohon kepadaMu kebaikan negeri ini dan kebaikan penduduknya, dan kami berlindung kepadaMu dari kejahatannya, kejahatan penduduknya dan kejahatan apa yang ada di dalamnya.", "Sebelum memasuki bandar atau bandar.", "Nabi ﷺ membaca ini setiap kali baginda ingin memasuki sebuah bandar."),
        "dua_vehicle_stumbles" to DuaText("Apabila Kenderaan Tersandung", "Dengan nama Allah.", "Apabila tunggangan atau kenderaan tergelincir atau tersandung, bukannya berkata 'Semoga syaitan binasa'.", "Mengucap Bismillah membuat syaitan mengecil seukuran lalat."),
        "dua_ajz_kasal_haram" to DuaText("Berlindung dari Kelemahan dan Usia Tua", "Ya Allah, aku berlindung kepada-Mu dari kelemahan dan kemalasan, dari pengecut dan usia tua, dari fitnah hidup dan mati, dan dari siksa kubur.", "Doa perlindungan harian yang komprehensif.", "Doa yang sering dilakukan oleh Nabi ﷺ."),
    )
}
